"""FTOK (kai, S1ENG_FTOK): an exact, faster tail tokenizer for ASCII tails (backlog lever 4a).

With TOK_TAIL (prompt.Encoder.enable_tail) every decision's ids are the template's fixed ids plus the ids of the text
after '{"evidence":', through tokenizers' encode_batch_fast: 85-113 us of request-thread time per decision on the
host profile (hostprof stages_out.txt), most of it outside BPE (Encoding objects, offsets, normalizer alignments).
FTOK encodes that tail with ftokc.so (source ftokc.c, build line in KERNELS.md): the added-token split, the
pre-tokenizer regex and the byte-level BPE merges of the model's own tokenizer, for ASCII text only. A non-ASCII
tail (where NFC and the Unicode classes matter) or one ftokc.so declines (a pre-token over 256 bytes) goes through
tokenizers exactly as before. Every validator tail generated by engrunner.fresh_decisions is ASCII.

Exactness:
  * at start-up (setup): the tokenizer object's own configuration (to_str()) must be the one ftokc.c implements
    (normalizer a Unicode normal form, the Qwen Split regex - tokenizer.json's or transformers' [\\p{L}\\p{M}]
    variant, equal on ASCII - then ByteLevel without regex or prefix space, BPE without dropout / unk / prefixes,
    added tokens matched raw, no truncation / padding); its vocab and merges fill ftokc.so's tables; then the ids of
    every tail_samples() tail and of a random sample (adversarial ASCII and random prompts, fresh seed, logged)
    must equal the tokenizers tail encode's. Any difference or error: "lever not used: ftok (...)", the tail encode
    stays tokenizers', nothing else changes;
  * offline (tests/test_ftok.py): >= 1,000,000 validator tails (engrunner.fresh_decisions, the request JSON round
    trip and prompt_text as server.Engine.decide builds them) and adversarial ASCII / Unicode, ids equal.

Switch: ACTIVE (module global) is read on every tail encode. S1ENG_FTOK=1 sets it at start-up (default 0: off); the
ARMS key "ftok" (model.BatchLoop._apply_arm) sets it at run time, and under MPF the GPU process sends it to every
worker (mpf.Front.ctl_all -> the worker's result pipe, a K_CTL record), so one engine can A/B it. The start-up check
runs when S1ENG_FTOK=1 or some S1ENG_ARMS arm has "ftok": 1; otherwise main.py and the MPF workers skip this module
and the engine is combine B's.
"""
from __future__ import annotations

import ctypes
import json
import os
import random
import string

ACTIVE = False          # the per-request switch (S1ENG_FTOK, ARMS key ftok)
OK = False              # this process's start-up check passed (and, in the GPU process under MPF, every worker's)
WHY = "not set up"      # why not, when OK is False
LIB = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ftokc.so")
MAXW = 256              # ftokc.c FTOK_MAXW
ABI = 1
N_RANDOM = 1500         # random tails in the start-up check (plus every tail_samples() tail)

SPLIT_RE = ("(?i:'s|'t|'re|'ve|'m|'ll|'d)|[^\\r\\n\\p{L}\\p{N}]?\\p{L}+|\\p{N}| ?[^\\s\\p{L}\\p{N}]+[\\r\\n]*|"
            "\\s*[\\r\\n]+|\\s+(?!\\S)|\\s+")
# transformers' Qwen2Tokenizer pattern (tokenizer_config.json pretokenize_regex): \p{M} has no ASCII member, so on
# ASCII text it matches exactly what SPLIT_RE matches
SPLIT_RE_M = ("(?i:'s|'t|'re|'ve|'m|'ll|'d)|[^\\r\\n\\p{L}\\p{N}]?[\\p{L}\\p{M}]+|\\p{N}| ?[^\\s\\p{L}\\p{M}\\p{N}]+"
              "[\\r\\n]*|\\s*[\\r\\n]+|\\s+(?!\\S)|\\s+")
UNICODE_FORMS = ("NFC", "NFD", "NFKC", "NFKD")   # each is the identity on ASCII


def ftok_of(v) -> int:
    """ARMS key / env value: 0 or 1 (int(v)), else ValueError."""
    x = int(v)
    if x not in (0, 1):
        raise ValueError(f"ftok must be 0 or 1 (got {v!r})")
    return x


def _arms(env) -> dict:
    a = env.get("S1ENG_ARMS", "")
    if not a:
        return {}
    try:
        d = json.loads(open(a[1:]).read() if a.startswith("@") else a)
    except Exception:  # noqa: BLE001 - BatchLoop reports an unreadable ARMS itself
        return {}
    return d if isinstance(d, dict) else {}


def wanted(env=os.environ) -> tuple[int, bool]:
    """(the env default of the switch, whether the start-up check runs: env on or some arm asks for ftok 1)."""
    try:
        on = ftok_of(env.get("S1ENG_FTOK", "0") or "0")
    except (TypeError, ValueError):
        on = 0
    asked = False
    for arm in _arms(env).values():
        try:
            asked = asked or (isinstance(arm, dict) and "ftok" in arm and ftok_of(arm["ftok"]) == 1)
        except (TypeError, ValueError):
            pass
    return on, bool(on or asked)


def set_active(v) -> None:
    global ACTIVE
    ACTIVE = bool(ftok_of(v)) and OK


def bytes_to_unicode() -> dict:
    """GPT-2's byte -> printable character map (tokenizers' ByteLevel)."""
    bs = list(range(ord("!"), ord("~") + 1)) + list(range(ord("\xa1"), ord("\xac") + 1)) + \
        list(range(ord("\xae"), ord("\xff") + 1))
    cs = bs[:]
    n = 0
    for b in range(256):
        if b not in bs:
            bs.append(b)
            cs.append(256 + n)
            n += 1
    return {b: chr(c) for b, c in zip(bs, cs)}


def config_why(j: dict) -> str:
    """'' when the tokenizer configuration (Tokenizer.to_str() JSON) is the one ftokc.c implements, else why not."""
    if j.get("truncation") is not None or j.get("padding") is not None:
        return "truncation / padding set"
    nm = j.get("normalizer")
    parts = nm.get("normalizers") if isinstance(nm, dict) and nm.get("type") == "Sequence" else [nm]
    if any(p is not None and (not isinstance(p, dict) or p.get("type") not in UNICODE_FORMS) for p in parts or []):
        return f"normalizer {json.dumps(nm)[:80]}"
    pt = j.get("pre_tokenizer") or {}
    seq = pt.get("pretokenizers") if pt.get("type") == "Sequence" else None
    if not seq or len(seq) != 2:
        return f"pre-tokenizer {json.dumps(pt)[:80]}"
    sp, bl = seq
    if (sp.get("type") != "Split" or sp.get("behavior") != "Isolated" or sp.get("invert")
            or (sp.get("pattern") or {}).get("Regex") not in (SPLIT_RE, SPLIT_RE_M)):
        return f"split {json.dumps(sp)[:120]}"
    if bl.get("type") != "ByteLevel" or bl.get("add_prefix_space") or bl.get("use_regex"):
        return f"byte level {json.dumps(bl)[:80]}"
    pp = j.get("post_processor")
    pps = pp.get("processors") if isinstance(pp, dict) and pp.get("type") == "Sequence" else [pp]
    if any(p is not None and p.get("type") not in ("ByteLevel", "TemplateProcessing") for p in pps or []):
        return f"post-processor {json.dumps(pp)[:80]}"   # (with add_special_tokens=False neither adds ids)
    m = j.get("model") or {}
    if (m.get("type") != "BPE" or m.get("dropout") not in (None, 0, 0.0) or m.get("unk_token") is not None
            or m.get("continuing_subword_prefix") not in (None, "") or m.get("end_of_word_suffix") not in (None, "")
            or m.get("fuse_unk") or m.get("byte_fallback") or m.get("ignore_merges")):
        return f"model {json.dumps({k: v for k, v in m.items() if k not in ('vocab', 'merges')})[:120]}"
    for a in j.get("added_tokens") or []:
        if a.get("normalized") or a.get("lstrip") or a.get("rstrip") or a.get("single_word") or not a.get("content"):
            return f"added token {json.dumps(a)[:80]}"
    return ""


class Fast:
    """ftokc.so with its tables, built from a tokenizers.Tokenizer (its to_str() JSON). encode(t) -> ids, or None
    when ftokc.so declines t (non-ASCII, a pre-token over MAXW bytes)."""

    class _Ctx(ctypes.Structure):
        _fields_ = [("mkey", ctypes.c_void_p), ("mval", ctypes.c_void_p), ("mask", ctypes.c_uint64),
                    ("byte_id", ctypes.c_void_p), ("added", ctypes.c_void_p), ("added_off", ctypes.c_void_p),
                    ("added_len", ctypes.c_void_p), ("added_id", ctypes.c_void_p), ("n_added", ctypes.c_int32),
                    ("first", ctypes.c_uint8 * 256)]

    def __init__(self, rust, lib_path: str | None = None, tok_json: str | None = None):
        j = json.loads(tok_json if tok_json is not None else rust.to_str())
        why = config_why(j)
        if why:
            raise ValueError(f"tokenizer configuration not supported: {why}")
        if getattr(rust, "encode_special_tokens", False):
            raise ValueError("encode_special_tokens is on")
        lib = ctypes.CDLL(lib_path or LIB)   # CDLL: the GIL is released during every call
        lib.ftok_abi.restype = ctypes.c_int
        if lib.ftok_abi() != ABI:
            raise ValueError(f"ftokc.so ABI {lib.ftok_abi()} != {ABI}")
        m = j["model"]
        vocab = m["vocab"]
        b2u = bytes_to_unicode()
        missing = [b for b in range(256) if b2u[b] not in vocab]
        if missing:
            raise ValueError(f"byte-level symbols missing from the vocab: {missing[:8]}")
        self.byte_id = (ctypes.c_int32 * 256)(*[vocab[b2u[b]] for b in range(256)])
        merges = [tuple(x) if isinstance(x, list) else tuple(x.split(" ", 1)) for x in m["merges"]]
        a = [vocab[x] for x, _ in merges]
        b = [vocab[y] for _, y in merges]
        nid = [vocab[x + y] for x, y in merges]
        n = len(merges)
        slots = 1 << max(10, (2 * n).bit_length())
        self.mkey = (ctypes.c_uint64 * slots)()
        self.mval = (ctypes.c_uint64 * slots)()
        added = [(t["content"].encode("utf-8"), int(t["id"])) for t in j.get("added_tokens") or []]
        blob = b"".join(c for c, _ in added)
        offs, o = [], 0
        for c, _ in added:
            offs.append(o)
            o += len(c)
        self.added = ctypes.create_string_buffer(blob, len(blob) + 1)
        self.added_off = (ctypes.c_int32 * max(1, len(added)))(*offs)
        self.added_len = (ctypes.c_int32 * max(1, len(added)))(*[len(c) for c, _ in added])
        self.added_id = (ctypes.c_int32 * max(1, len(added)))(*[i for _, i in added])
        ctx = self._Ctx()
        ctx.mkey, ctx.mval, ctx.mask = ctypes.addressof(self.mkey), ctypes.addressof(self.mval), slots - 1
        ctx.byte_id = ctypes.addressof(self.byte_id)
        ctx.added, ctx.added_off = ctypes.addressof(self.added), ctypes.addressof(self.added_off)
        ctx.added_len, ctx.added_id = ctypes.addressof(self.added_len), ctypes.addressof(self.added_id)
        ctx.n_added = len(added)
        for c, _ in added:
            ctx.first[c[0]] = 1
        self.ctx = ctx
        I32 = ctypes.c_int32
        lib.ftok_put.restype = ctypes.c_int
        lib.ftok_put.argtypes = (ctypes.c_void_p, ctypes.POINTER(I32), ctypes.POINTER(I32), ctypes.POINTER(I32),
                                 ctypes.POINTER(I32), ctypes.c_int64)
        if lib.ftok_put(ctypes.addressof(ctx), (I32 * n)(*a), (I32 * n)(*b), (I32 * n)(*range(n)), (I32 * n)(*nid),
                        n) != 0:
            raise ValueError("merge table full")
        lib.ftok_get.restype = ctypes.c_int64
        lib.ftok_get.argtypes = (ctypes.c_void_p, I32, I32, ctypes.POINTER(I32))
        # every merge must read back as itself (rank, id), the last of duplicates winning as in tokenizers' map
        last = {}
        for r, (x, y, z) in enumerate(zip(a, b, nid)):
            last[(x, y)] = (r, z)
        out = I32()
        for (x, y), (r, z) in last.items():
            if lib.ftok_get(ctypes.addressof(ctx), x, y, ctypes.byref(out)) != r or out.value != z:
                raise ValueError(f"merge table: pair {(x, y)} does not read back")
        self.n_merges, self.slots, self.n_added = n, slots, len(added)
        self.lib = lib
        fn = lib.ftok_encode
        fn.restype = ctypes.c_int
        fn.argtypes = (ctypes.c_void_p, ctypes.c_char_p, ctypes.c_int, ctypes.POINTER(I32), ctypes.c_int)
        cp = ctypes.addressof(ctx)

        def encode(t: str, _keep=self):   # _keep: the tables live as long as this function
            bt = t.encode("utf-8", "surrogatepass")
            nb = len(bt)
            buf = (I32 * (nb + 1))()
            r = fn(cp, bt, nb, buf, nb)
            return buf[:r] if r >= 0 else None

        def code(t: str) -> int:
            """ftok_encode's return value for t: the id count, or -1 / -2 / -3 (ftokc.c)"""
            bt = t.encode("utf-8", "surrogatepass")
            return fn(cp, bt, len(bt), (I32 * (len(bt) + 1))(), len(bt))
        self.encode, self.code = encode, code


def make_tail(hf, fast):
    """The tail encoder with FTOK: ftokc.so's ids for an ASCII tail while ACTIVE, tokenizers' otherwise."""
    def tail(t: str) -> list:
        if ACTIVE and t.isascii():
            ids = fast(t)
            if ids is not None:
                return ids
        return hf(t)
    tail.ftok_hf = hf
    return tail


# ----------------------------------------------------------------------------------------------- check samples
_ADDED = ["<|im_start|>", "<|im_end|>", "<|endoftext|>", "<think>", "</think>", "<tool_call>", "</tool_response>",
          "<tts_text_bos>", "<tts_text_bos_single>", "<|audio_pad|>", "<|fim_pad|>"]
_BROKEN = ["<|im_end", "<|im_start|", "<think", "</think", "<<think>>", "<|im_end|>>", "<|", "|>", "<", ">",
           "<tts_text_bos_singl", "< think>", "<THINK>", "<|IM_END|>"]
_CONTR = ["'s", "'S", "'t", "'T", "'re", "'RE", "'Re", "'rE", "'ve", "'VE", "'m", "'M", "'ll", "'LL", "'Ll", "'d",
          "'D", "'x", "'", "''", "'sa", "'llama", "'red", "'m'", "' s", "'\n", "'1"]
_WORDS = ["the", "The", "THE", "description", "letter", "options", "criterion", "evidence", "ref", "a", "I", "x",
          "nostalgic", "Looking", "forward", "with", "optimism", "parcel", "arrived", "late", "Nadia", "kettle"]
_WS = " \t\n\r\x0b\x0c"
_CTRL = [chr(i) for i in range(32)] + ["\x7f"]


def adversarial_ascii(rng: random.Random, max_pieces: int = 40) -> str:
    """One adversarial ASCII string: words in every case, contractions, long numbers, punctuation and whitespace
    runs, control characters, added tokens whole and broken, JSON escapes, the occasional letter run near MAXW."""
    out = []
    for _ in range(rng.randint(1, max_pieces)):
        k = rng.random()
        if k < 0.18:
            w = rng.choice(_WORDS) if rng.random() < 0.5 else \
                "".join(rng.choice(string.ascii_letters) for _ in range(rng.randint(1, 14)))
            out.append(w)
        elif k < 0.28:
            out.append(rng.choice(_CONTR))
        elif k < 0.38:
            out.append("".join(rng.choice(string.digits) for _ in range(rng.randint(1, 60))))
        elif k < 0.48:
            out.append("".join(rng.choice(string.punctuation) for _ in range(rng.randint(1, 6))))
        elif k < 0.62:
            if rng.random() < 0.2:
                out.append(rng.choice(" \t\n") * rng.randint(2, 40))
            else:
                out.append("".join(rng.choice(_WS) for _ in range(rng.randint(1, 8))))
        elif k < 0.68:
            out.append("".join(rng.choice(_CTRL) for _ in range(rng.randint(1, 4))))
        elif k < 0.74:
            out.append(rng.choice(_ADDED))
        elif k < 0.80:
            out.append(rng.choice(_BROKEN))
        elif k < 0.86:
            out.append(rng.choice(['\\"', "\\n", "\\t", "\\\\", "\\u00e9", '{"a": 1}', '": "', '", "', "[]", "{}",
                                   "-0.0", "1e+30", "3.14159", "NaN", "-Infinity", "null", "true"]))
        elif k < 0.863:
            out.append("".join(rng.choice(string.ascii_letters) for _ in range(rng.randint(240, 270))))
        else:
            out.append("".join(chr(rng.randint(0, 127)) for _ in range(rng.randint(1, 12))))
    return "".join(out)


def random_prompt_tail(rng: random.Random) -> str:
    """The tail of a prompt (prompt_text, as decide builds it) with random ASCII evidence, criterion and options."""
    from .prompt import _HEAD, prompt_text

    def val(d=0):
        k = rng.random()
        if k < 0.35 or d > 2:
            s = adversarial_ascii(rng, 12)
            return f"[ref {rng.getrandbits(32):08x}] {s}" if rng.random() < 0.3 else s
        if k < 0.5:
            return rng.choice([rng.randint(-10**12, 10**12), rng.random() * 10 ** rng.randint(-5, 20), None, True,
                               False, 0, -0.0])
        if k < 0.75:
            return [val(d + 1) for _ in range(rng.randint(0, 4))]
        return {adversarial_ascii(rng, 3): val(d + 1) for _ in range(rng.randint(0, 4))}
    opts = [f"{adversarial_ascii(rng, 2)}: {adversarial_ascii(rng, 6)}" for _ in range(rng.randint(1, 16))]
    text = prompt_text(val(), adversarial_ascii(rng, 8), opts)
    pre = _HEAD + '{"evidence":'
    return text[len(pre):]


def check(fast, hf, tails, code=None) -> str:
    """'' when fast(t) == hf(t) for every ASCII t, else the first difference. fast may decline (None) only a tail
    with a pre-token over MAXW bytes (code(t) == -2); with code None it may not decline at all."""
    for t in tails:
        if not t.isascii():
            continue
        got = fast(t)
        if got is None:
            if code is None or code(t) != -2:
                return f"declined {t[:48]!r}"
            continue
        want = hf(t)
        if list(got) != list(want):
            return f"ids differ on {t[:48]!r}"
    return ""


def setup(enc, env=os.environ, seed: int | None = None, n_random: int = N_RANDOM) -> str:
    """Switch FTOK on for `enc` (a prompt.Encoder with the tail encode on). Returns the start-up line: "lever used:
    ftok ..." or "lever not used: ftok (<why>)"; on any refusal or exception enc is left as it was."""
    global OK, WHY, ACTIVE
    OK, ACTIVE = False, False
    try:
        line = _setup(enc, env, seed, n_random)
    except Exception as exc:  # noqa: BLE001 - FTOK must never stop the engine from serving
        line = f"{type(exc).__name__}: {exc}"
    if not OK:
        WHY = line
        return f"lever not used: ftok ({line})"
    WHY = ""
    return line


def merge_workers(reports: dict) -> str:
    """GPU process under MPF (S1ENG_MPF), after the gate: each worker's FTOK outcome ('' = used, else why not, from
    its start-up report). Any worker without FTOK: OK / ACTIVE off here too, so an ARMS arm with ftok 1 is refused
    (BatchLoop._apply_arm) instead of measuring a mix. Returns the start-up line."""
    global OK, ACTIVE, WHY
    bad = [f"mpf worker {k}: {why}" for k, why in sorted(reports.items()) if why != ""]
    if not bad:
        return f"lever used: ftok in all {len(reports)} MPF workers"
    OK, ACTIVE = False, False
    WHY = "; ".join(bad)
    return f"lever not used: ftok ({WHY})"


def _setup(enc, env, seed, n_random) -> str:
    global OK, ACTIVE
    from .prompt import _HEAD, tail_samples

    hf = getattr(enc, "_tail", None)
    if hf is None or getattr(enc, "rust", None) is None:
        return "the tail encode is off: S1ENG_TOK_TAIL"
    hf = getattr(hf, "ftok_hf", hf)
    on, _ = wanted(env)
    F = Fast(enc.rust)
    fast = F.encode
    pre = _HEAD + '{"evidence":'
    samples = [t[len(pre):] for t in tail_samples()]
    seed = int.from_bytes(os.urandom(4), "little") if seed is None else seed
    rng = random.Random(seed)
    rand = [adversarial_ascii(rng) if i % 2 else random_prompt_tail(rng) for i in range(n_random)]
    why = check(fast, hf, samples) or check(fast, hf, rand, F.code)
    if why:
        return why
    tail = make_tail(hf, fast)
    prev = ACTIVE
    ACTIVE = True   # the whole-prompt check runs the new path
    try:
        for t in tail_samples():
            if enc._pre_ids + tail(t[len(pre):]) != enc.encode_full(t):
                return f"whole-prompt ids differ on {t[len(pre):len(pre) + 48]!r}"
    finally:
        ACTIVE = prev
    enc._tail = tail
    OK = True
    ACTIVE = bool(on)
    return (f"lever used: ftok (exact ASCII tail tokenizer ftokc.so: {len(samples)} sample + {n_random} random tails "
            f"(seed {seed}) equal to tokenizers'; switch {'on' if on else 'off'} "
            f"(S1ENG_FTOK / ARMS key ftok))")
